import { WHATSAPP_NOTICE_VERSION } from '../../server/sarin/whatsapp/consent.js';
import test from 'node:test';
import assert from 'node:assert/strict';
import {processorFixture,establishConsent,latest} from './sarin-whatsapp-processor-fixture.mjs';
const impl=await import('../../server/sarin/whatsapp/processor.js').catch(e=>{if(e.code==='ERR_MODULE_NOT_FOUND')return {};throw e;});
const process=(...args)=>{assert.equal(typeof impl.processWhatsAppWork,'function','Falta procesador');return impl.processWhatsAppWork(...args);};
const run=(f,j,fetch=f.fetch)=>process(j,f.env,{store:f.store,now:f.now,fetch});
const posts=f=>f.calls.filter(c=>c.url.includes('ycloud')&&c.init.method==='POST');
test('duplicate_queue_one_inference_one_post',async t=>{const f=await processorFixture(t);await establishConsent(f,process);const j=await f.capture();await Promise.all([run(f,j),run(f,j)]);await run(f,j);assert.equal(f.calls.filter(c=>c.url.includes('deepseek')).length,2);assert.equal(posts(f).length,1);});
for(const phase of ['classification','generation'])test('pause_'+(phase==='classification'?'during_classification_prevents_generation':'after_generation_prevents_post'),async t=>{const f=await processorFixture(t);await establishConsent(f,process);const j=await f.capture();let n=0;await run(f,j,async(...args)=>{const r=await f.fetch(...args);if(++n===(phase==='classification'?1:2))await f.pause();return r;});assert.equal(f.calls.length,phase==='classification'?1:2);assert.equal(posts(f).length,0);});
test('crash_after_saved_reply_only_sends',async t=>{const f=await processorFixture(t);await establishConsent(f,process);const j=await f.capture(),token=crypto.randomUUID();await f.store.claimGeneration({...j,token});await f.store.markInferenceStarted({...j,token});await f.store.completeGeneration({...j,token,reply:'Respuesta ya guardada',outcome:'completed'});f.setTime(f.now()+120001);await f.store.expireLeases({limit:1});await run(f,j);assert.equal(f.calls.length,1);assert.equal(posts(f).length,1);});
test('post_timeout_is_terminal_uncertain',async t=>{const f=await processorFixture(t),j=await f.capture();let calls=0;await run(f,j,async()=>{calls++;throw new Error('synthetic timeout');});await run(f,j);assert.equal(calls,1);assert.equal(latest(f,'sarin_wa_outbox').state,'send_uncertain');assert.equal(latest(f,'sarin_wa_send_quota').consumed,1);});
test('queue_old_epoch_is_inert',async t=>{const f=await processorFixture(t),j=await f.capture();await run(f,{...j,epoch:crypto.randomUUID()});assert.equal(f.calls.length,0);});
test('expired_window_no_post',async t=>{const f=await processorFixture(t),j=await f.capture();f.setTime(f.now()+86400001);await run(f,j);assert.equal(f.calls.length,0);});
test('no_delivered_reply_in_history',async t=>{const f=await processorFixture(t);await establishConsent(f,process);const j=await f.capture();await run(f,j);assert.deepEqual(JSON.parse(JSON.parse(f.calls[0].init.body).messages[1].content).history,[]);const blocked=await f.capture();await run(f,blocked);assert.equal(posts(f).length,1);});
test('dead_consumer_does_not_restart_ai',async t=>{const f=await processorFixture(t);await establishConsent(f,process);const j=await f.capture(),token=crypto.randomUUID();await f.store.claimGeneration({...j,token});await f.store.markInferenceStarted({...j,token});f.setTime(f.now()+120001);await impl.dispatchWhatsAppWork(f.env,{store:f.store,now:f.now});await run(f,j);assert.equal(f.calls.length,0);assert.equal(latest(f,'sarin_wa_jobs').state,'inference_uncertain');});
test('queue_publish_failure_is_recovered',async t=>{const f=await processorFixture(t);await f.capture();f.env.SARIN_WHATSAPP_QUEUE.send=async()=>{throw Error('offline');};assert.equal((await impl.dispatchWhatsAppWork(f.env,{store:f.store,now:f.now})).published,0);f.env.SARIN_WHATSAPP_QUEUE.send=async hint=>f.hints.push(hint);assert.equal((await impl.dispatchWhatsAppWork(f.env,{store:f.store,now:f.now})).published,1);assert.deepEqual(Object.keys(f.hints[0]).sort(),['epoch','jobId']);});
test('disabled_or_incomplete_configuration_never_spends',async t=>{for(const key of ['SARIN_WHATSAPP_SEND_ENABLED','SARIN_WHATSAPP_API_KEY','SARIN_IP_SECRET','DEEPSEEK_API_KEY','SARIN_WHATSAPP_QUEUE']){const f=await processorFixture(t),j=await f.capture();delete f.env[key];await run(f,j);assert.equal(f.calls.length,0);assert.equal(latest(f,'sarin_wa_outbox'),undefined);}const f=await processorFixture(t),j=await f.capture();f.env.SARIN_WHATSAPP_REPLIES_ENABLED='false';await run(f,j);assert.equal(latest(f,'sarin_wa_pilot').enabled,0);});
test('synthetic_resource_measurements',async t=>{const f=await processorFixture(t);for(const [label,text] of [['notice','Hola'],['confirm','ACEPTO'],['generation','Necesito una tienda']]){const j=await f.capture(text);f.reset();await run(f,j);t.diagnostic(label+' '+JSON.stringify(f.counts));const o=latest(f,'sarin_wa_outbox');assert.ok(o);await f.store.applyStatus({eventId:label+'_delivery',providerId:o.provider_id,status:'delivered',at:f.now()});}});
test('actual_post_timeout_aborts_and_never_reposts',async t=>{t.mock.timers.enable({apis:['setTimeout']});const f=await processorFixture(t),j=await f.capture();let started,signal,count=0;const ready=new Promise(r=>started=r);const promise=run(f,j,async(url,init)=>{count++;signal=init.signal;started();return new Promise(()=>{});});await ready;t.mock.timers.tick(10001);await promise;assert.equal(signal.aborted,true);assert.equal(latest(f,'sarin_wa_outbox').state,'send_uncertain');await run(f,j);assert.equal(count,1);});
test('global_deadline_prevents_late_generation_or_post',async t=>{const f=await processorFixture(t);await establishConsent(f,process);const j=await f.capture();await run(f,j,async(...args)=>{const response=await f.fetch(...args);f.setTime(f.now()+60001);return response;});assert.equal(f.calls.length,1);assert.equal(latest(f,'sarin_wa_jobs').state,'inference_uncertain');});
test('ready_output_wrong_configured_recipient_never_consumes_attempt',async t=>{const f=await processorFixture(t),j=await f.capture(),token=crypto.randomUUID();await f.store.claimGeneration({...j,token});await f.store.createFixedReply({...j,token,purpose:'notice',text:'Aviso',version:WHATSAPP_NOTICE_VERSION,hash:'a'.repeat(64)});f.setTime(f.now()+120001);await f.store.expireLeases({limit:1});f.env.SARIN_WHATSAPP_PILOT_PHONES='["+573000000099"]';await run(f,j);assert.equal(f.calls.length,0);assert.equal(latest(f,'sarin_wa_send_quota').consumed,0);});
